// @ts-strict-ignore
import styles from "./birth-date-field.module.less";
import { useState, KeyboardEvent, useEffect, useRef, RefObject, KeyboardEventHandler } from "react";
import {
  isValidDayInGenericMonth,
  isValidMonth,
  isValidBirthYear,
  isValidDayInMonth,
} from "@/core/helpers/validation-helper";
import { addLeadingZero } from "@/core/helpers/string-helper";
import { FormField, assignToRefs } from "@/core/helpers/form-builder";
import { useTranslation } from "react-i18next";
import InputField from "@/core/components/primitives/input-field/input-field";
import InputError from "@/core/components/primitives/input-error/input-error";
import InputLabel from "@/core/components/primitives/input-label/input-label";

type BirthDateFieldProps = {
  onChange?: (name: string, value: string) => void;
  value?: string;
  label?: string;
  yearLabel?: string;
  monthLabel?: string;
  dayLabel?: string;
  name?: string;
  errorText?: string;
  isRequired?: boolean;
  isValid?: boolean;
  triggerOnChangeForYearChange?: boolean;
  isEditable?: boolean;
  formField: FormField;
  inputRef?: RefObject<HTMLInputElement | null>;
  onKeyDown?: KeyboardEventHandler<HTMLInputElement>;
};

const BirthDateField = ({
  label,
  name,
  value,
  isRequired,
  isValid,
  triggerOnChangeForYearChange,
  isEditable,
  errorText,
  formField,
  inputRef,
  onChange,
  onKeyDown,
}: BirthDateFieldProps) => {
  if (formField) {
    label = label ?? formField.label;
    name = name ?? formField.name;
    value = value ?? formField.value;
    isRequired = isRequired ?? formField.isRequired;
    isValid = isValid ?? formField.isValid;
    errorText = errorText ?? formField.errorText;
    isEditable = isEditable ?? formField.isEditable;
  }
  const { t } = useTranslation();
  const valueSplitted = value && value !== "--" ? value.split("-") : [];
  const [year, setYear] = useState(valueSplitted[0] ?? "");
  const [month, setMonth] = useState(valueSplitted[1] ?? "");
  const [day, setDay] = useState(valueSplitted[2] ?? "");
  const isOnChangeSet = typeof onChange === "function";

  const yearRef = useRef<HTMLInputElement>(null);
  const monthRef = useRef<HTMLInputElement>(null);
  const dayRef = useRef<HTMLInputElement>(null);

  const displayError = isValid === false;

  useEffect(() => {
    // used when value is set after initial render
    setYear(valueSplitted[0] ?? "");
    setMonth(valueSplitted[1] || "");
    setDay(valueSplitted[2] || "");
    // we check if value is set, rather than the splitted value
    // otherwise it will create an infinite loop
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  useEffect(() => {
    if (value === "--") {
      // Reset value to prevent faulty validation check on refresh
      onChange(name, "");
    }
  }, [value, name, onChange]);

  useEffect(() => {
    if (!isOnChangeSet) {
      return;
    }

    const hasAllFields = Boolean(year && month && day);
    const currentValue = `${year}-${month}-${day}`;
    if (hasAllFields && value !== currentValue) {
      onChange(name, currentValue);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [year, day, month, isOnChangeSet, name, value]);

  const isValidDay = () => {
    if (isValidMonth(month) && isValidBirthYear(year)) {
      return isValidDayInMonth(year, month, day);
    }

    return isValidDayInGenericMonth(day);
  };

  const onChangeYear = (value: string) => {
    if (!isOnChangeSet) {
      return;
    }

    if (isValidBirthYear(value)) {
      if (monthRef && monthRef.current && !month) {
        monthRef.current.focus();
      }
    }
    setYear(value);
    if (triggerOnChangeForYearChange) {
      onChange(name, `${value}-${month}-${day}`); // immediate check for year changes
    }
  };

  const onChangeMonth = (value: string) => {
    if (!isOnChangeSet) {
      return;
    }

    if (isValidMonth(value) && value.length === 2 && !day) {
      if (dayRef && dayRef.current) {
        dayRef.current.focus();
      }
    }
    setMonth(value);
  };

  const onChangeDay = (value: string) => {
    if (!isOnChangeSet) {
      return;
    }

    setDay(value);
  };

  const onBlurDay = (value: string) => {
    if (isValidDayInGenericMonth(value) && value.length === 1) {
      setDay(addLeadingZero(value));
    }
  };

  const onBlurMonth = (value: string) => {
    if (isValidMonth(value) && value.length === 1) {
      setMonth(addLeadingZero(value));
    }
  };

  const handleEmptyBackspace = (event: KeyboardEvent<HTMLInputElement>, ref: RefObject<HTMLInputElement>) => {
    if (event.key === "Backspace" && event.currentTarget.value === "") {
      if (ref && ref.current) {
        ref.current.focus();
      }
    }
  };

  const handleOnKeyDown =
    (localHandler?: KeyboardEventHandler<HTMLInputElement>) => (event: KeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event);
      if (event.defaultPrevented) {
        return;
      }
      localHandler?.(event);
    };

  return (
    <div className={styles.wrapper}>
      <InputLabel label={label} inputName={`${name}-year`} isRequired={isRequired} />
      <div className={styles.fieldsWrapper}>
        <InputField
          label={t("year")}
          maxLength={4}
          autoComplete="bday-year"
          inputMode="numeric"
          pattern="[0-9]*"
          inputRef={(e) => assignToRefs(e, yearRef, inputRef, formField?.inputRef)}
          placeholder={t("inputPlaceholderYear")}
          name={`${name}-year`}
          value={year}
          isEditable={isEditable}
          isValid={isValid === false ? isValidBirthYear(year) : null}
          onKeyDown={handleOnKeyDown()}
          onChange={(_, value) => onChangeYear(value)}
          isGroupedInput={true}
        />
        <InputField
          label={t("month")}
          maxLength={2}
          autoComplete="bday-month"
          inputMode="numeric"
          pattern="[0-9]*"
          inputRef={monthRef}
          placeholder={t("inputPlaceholderMonth")}
          name={`${name}-month`}
          value={month}
          isEditable={isEditable}
          isValid={isValid === false ? isValidMonth(month) : null}
          onKeyDown={handleOnKeyDown((e) => handleEmptyBackspace(e, yearRef))}
          onBlur={(event) => onBlurMonth(event.target.value)}
          onChange={(_, value) => onChangeMonth(value)}
          isGroupedInput={true}
        />
        <InputField
          label={t("day")}
          maxLength={2}
          autoComplete="bday-day"
          inputMode="numeric"
          pattern="[0-9]*"
          inputRef={dayRef}
          placeholder={t("inputPlaceholderDay")}
          name={`${name}-day`}
          value={day}
          isEditable={isEditable}
          isValid={isValid === false ? isValidDay() : null}
          onKeyDown={handleOnKeyDown((e) => handleEmptyBackspace(e, monthRef))}
          onBlur={(event) => onBlurDay(event.target.value)}
          onChange={(_, value) => onChangeDay(value)}
          isGroupedInput={true}
        />
      </div>
      <InputError showError={displayError} isRequired={isRequired} errorText={errorText} />
    </div>
  );
};

export default BirthDateField;
