import { multipleClassNames } from "@/core/helpers";
import RadioButtons from "@/core/components/primitives/radio-buttons/radio-buttons";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import styles from "./price-variation-selector.module.less";

const VariationRadioButtons = ({ variationName, isSelected }: { variationName: string; isSelected: boolean }) => {
  const { t } = useTranslation();

  return (
    <AnimatePresence initial={false}>
      {isSelected && (
        <motion.div
          key={variationName + "-selected"}
          initial={{ opacity: 0, scale: 0.5, y: "var(--foundation-spacing-x1)", x: "var(--foundation-spacing-x1)" }}
          animate={{ opacity: 1, scale: 1, y: 0, x: 0 }}
          exit={{ opacity: 0, y: "var(--foundation-spacing-x1)", x: "var(--foundation-spacing-x1)" }}
          transition={{ type: "tween", ease: "easeOut" }}
          className={styles.variationRadioButtonLabelWrapperSelected}
        >
          <span className={multipleClassNames(styles.variationRadioButtonLabelSelected, "body-xxs")}>
            {t("productBlockSelectPriceVariationChosen")}
          </span>
        </motion.div>
      )}
      <div data-is-selected={isSelected} className={styles.variationRadioButtonLabelWrapper}>
        <span className={multipleClassNames(styles.variationRadioButtonLabel, "body-s", "bold")}>{variationName}</span>
      </div>
    </AnimatePresence>
  );
};

type PriceVariationSelectorProps = {
  priceVariation: Array<number>;
  setSelectedPriceVariation: (value: number) => void;
  selectedPriceVariation: number | null;
};

export const PriceVariationSelector = ({
  priceVariation,
  setSelectedPriceVariation,
  selectedPriceVariation,
}: PriceVariationSelectorProps) => {
  const { t } = useTranslation();
  // Determine grid layout based on number of variations
  const isOddVariationCount = priceVariation.length > 1 && priceVariation.length % 2 !== 0;

  return (
    <div className={styles.priceVariationSection} data-use-three-columns={isOddVariationCount}>
      <AnimatePresence>
        <RadioButtons
          name="priceVariation"
          key="priceVariation"
          label={t("productBlockSelectPriceVariationLabel")}
          options={priceVariation.map((variation) => ({
            label: (
              <VariationRadioButtons
                variationName={`${variation}:-`}
                isSelected={selectedPriceVariation === variation}
              />
            ),
            value: variation.toString(),
          }))}
          value={selectedPriceVariation?.toString()}
          radioItemsWrapperClassName={multipleClassNames(styles.variationRadioButtonsWrapper)}
          onChange={(_: string, value: string) => {
            setSelectedPriceVariation(Number(value));
          }}
        />
      </AnimatePresence>
    </div>
  );
};
