import { PropsWithChildren, useEffect } from "react";
import styles from "./animation-pop.module.less";
import { useAnimation, motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";

type AnimationPopProps = {
  className?: string;
  containerClassName?: string;
};

const AnimationPop = ({
  className,
  containerClassName,
  children,
}: PropsWithChildren<AnimationPopProps>): JSX.Element => {
  const controls: ReturnType<typeof useAnimation> = useAnimation();

  useEffect(() => {
    controls.start({
      scale: 1,
      transition: {
        type: "spring",
        velocity: 10,
        stiffness: 700,
        damping: 80,
      },
    });
  }, [controls, children]);

  return (
    <motion.span
      animate={controls}
      className={multipleClassNames(className, containerClassName ? containerClassName : styles.container)}
    >
      {children}
    </motion.span>
  );
};

export default AnimationPop;
