import { CartRequestCartItem, DeliveryType, DynamicData, GiftInformationV1 } from "@parksandresorts/webapiproxy-types";
import { NormalizedProduct } from "../hooks";
import { throwError } from "./object-helper";

export type CartItemBuilderOptions = {
  receiverInfo?: GiftInformationV1;
  price?: number;
  isVariablePrice?: boolean;
  deliveryType: DeliveryType;
  quantity?: number;
};

/**
 * Shared utility to create standardized cart items
 * Handles both simple products and gift cards with variable pricing
 */
export const createCartItem = (product: NormalizedProduct, options: CartItemBuilderOptions): CartRequestCartItem => {
  const { receiverInfo, price, isVariablePrice = false, deliveryType, quantity = 1 } = options;
  const { scheduledDelivery } = receiverInfo || {};

  // Initialize data object for additional cart item metadata
  const data: Pick<DynamicData, "giftInformationV1" | "variablePriceV1"> = {};

  // Add gift information if provided
  if (receiverInfo) {
    data.giftInformationV1 = scheduledDelivery
      ? {
          ...receiverInfo,
          scheduledDelivery: {
            deliveryDate: scheduledDelivery.deliveryDate,
            // Modify deliveryTime to match expected format (hh:mm:ss)
            deliveryTime: `${scheduledDelivery.deliveryTime}:00`,
          },
        }
      : receiverInfo;
  }

  // Add variable price if specified
  if (isVariablePrice && price) {
    data.variablePriceV1 = price;
  }

  // Build cart item
  const cartItem: CartRequestCartItem = {
    productId: product.productId ?? throwError("Product must be purchasable GLK product"),
    quantity,
    deliveryType,
    data: Object.keys(data).length > 0 ? data : undefined,
  };

  return cartItem;
};

/**
 * Creates multiple identical cart items (useful for variable-price products with quantity > 1)
 */
export const createMultipleCartItems = (
  product: NormalizedProduct,
  options: CartItemBuilderOptions,
): Array<CartRequestCartItem> => {
  const quantity = options.quantity || 1;

  return Array.from({ length: quantity }, () => createCartItem(product, { ...options, quantity: 1 }));
};
