import { formatToSek } from "@/core/helpers";
import InputField from "@/core/components/primitives/input-field/input-field";
import { useTranslation } from "react-i18next";
import styles from "../product-block.module.less";
import { FormField } from "@/core/helpers/form-builder";
import { LabelKey } from "@/core/labels/i18n";

type CustomPriceProps = {
  customPrice: number | undefined;
  setCustomPrice: (value: number | undefined) => void;
  minCustomPrice: number;
  maxCustomPrice?: number;
  inputLabel: LabelKey;
  formField?: FormField;
  onChange: (name: string, value: string) => void;
};

export const CustomPrice = ({
  customPrice,
  setCustomPrice,
  minCustomPrice,
  maxCustomPrice,
  inputLabel,
  formField,
  onChange,
}: CustomPriceProps) => {
  const { t } = useTranslation();
  const helperText = maxCustomPrice
    ? t("productBlockCustomPriceHelperTextRange", {
        min: formatToSek(minCustomPrice),
        max: formatToSek(maxCustomPrice),
      })
    : t("productBlockCustomPriceHelperTextMin", { min: formatToSek(minCustomPrice) });
  const errorText = maxCustomPrice
    ? t("productBlockCustomPriceErrorTextRange", {
        min: formatToSek(minCustomPrice),
        max: formatToSek(maxCustomPrice),
      })
    : t("productBlockCustomPriceErrorTextMin", { min: formatToSek(minCustomPrice) });

  return (
    <div className={styles.customPriceSection}>
      <InputField
        formField={formField}
        name="customPrice"
        label={t(inputLabel)}
        type="text"
        inputMode="numeric"
        placeholder={t("productBlockCustomPricePlaceholder")}
        value={customPrice?.toString()}
        isValid={formField?.isValid !== false}
        helperText={helperText}
        errorText={errorText}
        onChange={(name, value) => {
          const unformatted = value.replace(/\D/g, "");
          setCustomPrice(unformatted === "" ? undefined : Number(unformatted));
          onChange(name, unformatted);
        }}
        className={styles.customPriceInput}
      />
    </div>
  );
};
