import { useEffect } from "react";
import { EventAggregator, isNonEmptyArray } from "@/core/helpers";
import { NormalizedProduct } from "@/core/hooks/product-hooks";

/**
 * Shared hook for tracking product views across different product components
 * Used by both product-block and giftable-product-block components
 */
export const useProductTracking = (product: NormalizedProduct | undefined) => {
  useEffect(() => {
    if (!product?.productId) return;

    EventAggregator.publish("trackEcommerce", {
      event: "productView",
      action: {
        detail: {
          products: [
            {
              name: product.name,
              price: product.price,
              category:
                product.contentfulProduct && isNonEmptyArray(product.contentfulProduct.tags)
                  ? product.contentfulProduct.tags[0].title
                  : product.glkProduct?.productType,
              glkId: product.productId,
            },
          ],
        },
      },
    });
  }, [product]);
};
