// @ts-strict-ignore
import { useEffect, useState } from "react";
import styles from "./product-new-card-form.module.less";
import BirthDateField from "@/core/components/primitives/birth-date-field/birth-date-field";
import ImageField from "@/core/components/primitives/image-field/image-field";
import InputField from "@/core/components/primitives/input-field/input-field";
import { useForm, buildField } from "@/core/helpers/form-builder";
import SessionStorageHelper from "@/core/helpers/session-storage-helper";
import { Form, FormField, saveFormValues, restoreFormValues } from "@/core/helpers/form-builder";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import DialogModal from "@/core/components/primitives/dialog-modal/dialog-modal";
import { AnimatePresence } from "framer-motion";
import useFocus from "@/core/hooks/use-focus";
import { useTranslation } from "react-i18next";
import { CartRequestCartItem, DeliveryType, ProductInformationResponseItem } from "@parksandresorts/webapiproxy-types";
import { useShopServiceCartContext } from "@/core/contexts";
import { useMutation } from "@tanstack/react-query";
import { NotificationHelper, getPrimaryDeliveryType } from "@/core/helpers";

const useRegisterNewCardForm = () => {
  const { t } = useTranslation();
  const initialForm: Form = {
    fields: new Map<string, FormField>()
      .set(
        "firstName",
        buildField("firstName", {
          label: t("firstName"),
          placeholder: t("inputPlaceholderFirstName"),
          type: "INPUT_FIELD",
          isRequired: true,
          autoComplete: "given-name",
        }),
      )
      .set(
        "lastName",
        buildField("lastName", {
          label: t("lastName"),
          placeholder: t("inputPlaceholderLastName"),
          type: "INPUT_FIELD",
          isRequired: true,
          autoComplete: "family-name",
        }),
      )
      .set(
        "postalCode",
        buildField("postalCode", {
          label: t("postalCode"),
          placeholder: t("inputPlaceholderPostalCode"),
          type: "INPUT_FIELD",
          isRequired: true,
          validationType: "ZIPCODE",
          errorText: t("inputValidationPostalCode"),
          autoComplete: "postal-code",
        }),
      )
      .set(
        "email",
        buildField("email", {
          label: t("email"),
          placeholder: t("inputPlaceholderEmail"),
          type: "INPUT_FIELD",
          isRequired: true,
          validationType: "EMAIL",
          errorText: t("inputValidationEmail"),
          autoComplete: "email",
        }),
      )
      .set(
        "mobileNumber",
        buildField("mobileNumber", {
          label: t("phone"),
          placeholder: t("inputPlaceholderPhone"),
          type: "INPUT_FIELD",
          isRequired: true,
          validationType: "PHONE",
          errorText: t("inputValidationPhone"),
          autoComplete: "tel",
        }),
      )
      .set(
        "dateOfBirth",
        buildField("dateOfBirth", {
          label: t("dateOfBirth"),
          type: "DATE_FIELD",
          isRequired: true,
          validationType: "BIRTHDATE",
          errorText: t("inputValidationDateOfBirth"),
          autoComplete: "bday",
        }),
      )
      .set(
        "image",
        buildField("image", {
          label: t("imageID"),
          type: "IMAGE_FIELD",
          helperText: t("imageIDHelperText"),
          isRequired: true,
        }),
      ),
  };

  const [form, isFormvalid, handleFieldOnChange, setForm, validateForm, , focusOn] = useForm(initialForm, true);

  return { initialForm, form, isFormvalid, handleFieldOnChange, setForm, validateForm, focusOn };
};

type ConfirmationDialogProps = {
  fields: Map<string, FormField>;
};

const ConfirmationDialog = ({ fields }: ConfirmationDialogProps) => {
  return (
    <ul className={styles.list}>
      {[...fields.values()]
        .filter((field) => field.name !== "image")
        .map((field) => {
          return (
            <li className={styles.listItem} key={field.name}>
              <span className={styles.fieldName}>{field.label}</span>
              <span>{field.value}</span>
            </li>
          );
        })}
    </ul>
  );
};

const ProductNewCardForm = ({ product }: { product: ProductInformationResponseItem }) => {
  const { t } = useTranslation();
  const formSessionStorageKey = `${product.id}-product-new-card-form`;
  const { initialForm, form, isFormvalid, handleFieldOnChange, setForm, validateForm, focusOn } =
    useRegisterNewCardForm();
  const [focusRef, setFocus] = useFocus<HTMLDivElement>();
  const [isConfirmationOpen, setIsConfirmationOpen] = useState(false);
  const [hasAddedToCart, setHasAddedToCart] = useState(false);
  const { addCartItem: addCartItemMutation } = useShopServiceCartContext();

  const { mutate: addToCart, isPending: addingToCart } = useMutation({
    mutationFn: async () => {
      setIsConfirmationOpen(false);

      const cartProduct = getShopServiceCartItems();
      await addCartItemMutation(cartProduct);

      NotificationHelper.addCartNotification({
        headline: t("addedToCartHeadline"),
        body: t("addedToCartBody"),
      });

      setHasAddedToCart(true);
      SessionStorageHelper.removeItem(formSessionStorageKey);
      restoreForm(initialForm);
    },
    onError: () => {
      NotificationHelper.addCartNotification({
        headline: t("somethingWentWrong"),
        body: t("tryAgain"),
      });
      setIsConfirmationOpen(false);
    },
  });

  const isAddingToCart = addingToCart || hasAddedToCart;

  useEffect(() => {
    restoreForm(form);
  }, []);

  useEffect(() => {
    saveFormValues(form, formSessionStorageKey, "sessionStorage", 0, ["image"]);
  }, [form, formSessionStorageKey]);

  const restoreForm = (form: Form) => {
    const restoredForm = restoreFormValues(form, formSessionStorageKey);
    setForm(restoredForm);
  };

  const onClickFormSubmit = () => {
    if (!isFormvalid) {
      validateForm();
      focusOn("FIRST_INVALID");
    } else {
      setIsConfirmationOpen(true);
    }
  };

  const getShopServiceCartItems = (): CartRequestCartItem => {
    const holderInformation = getHolderInformation();
    const deliveryType = getPrimaryDeliveryType({ glkProduct: product }, DeliveryType.DIGITAL);

    const productData: CartRequestCartItem = {
      productId: product.id,
      quantity: 1,
      deliveryType: deliveryType,
      data: { cardHolderInformationV1: holderInformation },
    };

    return productData;
  };

  const getHolderInformation = () => {
    const holderInformation = {
      dateOfBirth: form.fields.get("dateOfBirth").value.toString(),
      firstName: form.fields.get("firstName").value.toString(),
      lastName: form.fields.get("lastName").value.toString(),
      postalCode: form.fields.get("postalCode").value.toString(),
      email: form.fields.get("email").value.toString(),
      mobileNumber: form.fields.get("mobileNumber").value.toString(),
      image: form.fields.get("image").value.toString(),
    };

    return holderInformation;
  };

  function closeDialog() {
    setFocus();
    setIsConfirmationOpen(false);
  }

  return (
    <div ref={focusRef} tabIndex={-1} className={`${styles.wrapper}`}>
      <InputField formField={form.fields.get("firstName")} onChange={handleFieldOnChange} maxLength={50} />
      <InputField formField={form.fields.get("lastName")} onChange={handleFieldOnChange} maxLength={50} />
      <InputField formField={form.fields.get("postalCode")} onChange={handleFieldOnChange} maxLength={6} />
      <InputField formField={form.fields.get("email")} onChange={handleFieldOnChange} maxLength={75} />
      <InputField formField={form.fields.get("mobileNumber")} onChange={handleFieldOnChange} maxLength={50} />
      <BirthDateField formField={form.fields.get("dateOfBirth")} onChange={handleFieldOnChange} />
      <ImageField formField={form.fields.get("image")} onUserChanged={handleFieldOnChange} />
      <PrimaryButton
        isDisabled={isAddingToCart}
        label={isAddingToCart ? t("addingToCart") : t("continue")}
        isFullWidth={true}
        onClick={onClickFormSubmit}
      />
      <AnimatePresence>
        {isConfirmationOpen && (
          <DialogModal
            headingText={t("confirmDetails")}
            bodyText={<ConfirmationDialog fields={form.fields} />}
            primaryButtonText={t("addToCart")}
            primaryButtonAction={() => addToCart()}
            secondaryButtonText={t("change")}
            secondaryButtonAction={closeDialog}
            onCloseFunction={closeDialog}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default ProductNewCardForm;
