import { useEffect, forwardRef, useImperativeHandle } from "react";
import { useTranslation } from "react-i18next";
import { useForm, buildField, getGiftCardSettings, isNonEmptyArray } from "@/core/helpers";
import { PriceVariationSelector } from "./price-variation-selector";
import { CustomPrice } from "./custom-price";
import { GlkBackedProduct } from "@/core/hooks";

type GiftCardPriceSelectorProps = {
  product: GlkBackedProduct;
  selectedPriceVariation: number | null;
  setSelectedPriceVariation: (value: number | null) => void;
  customPrice: number | undefined;
  setCustomPrice: (value: number | undefined) => void;
};

// Export validation function type for consumers
export type GiftCardPriceSelectorRef = {
  validatePrice: () => boolean;
};

/**
 * Shared component for gift card price selection (fixed amounts + optional custom price)
 * Used in both direct purchase (gift-card-purchase-panel) and giftable multi-step flow (giftable-product-block/steps/product-step)
 */
export const GiftCardPriceSelector = forwardRef<GiftCardPriceSelectorRef, GiftCardPriceSelectorProps>(
  ({ product, selectedPriceVariation, setSelectedPriceVariation, customPrice, setCustomPrice }, ref) => {
    const { t } = useTranslation();
    const { giftCardFixedAmounts, hasCustomPrice, minGiftCardOptionalAmount, maxGiftCardOptionalAmount } =
      getGiftCardSettings(product);

    const hasFixedAmounts = isNonEmptyArray(giftCardFixedAmounts);

    // Custom price form validation
    const [customPriceForm, , handleCustomPriceFieldChange, setForm, , getFormValidation, focusOn] = useForm(
      {
        fields: new Map([
          [
            "customPrice",
            buildField("customPrice", {
              value: customPrice?.toString() || "",
              isRequired: !hasFixedAmounts && !!minGiftCardOptionalAmount,
              label: t("productBlockCustomPriceInputLabel"),
              type: "AMOUNT_FIELD",
              minValue: minGiftCardOptionalAmount,
              maxValue: maxGiftCardOptionalAmount,
            }),
          ],
        ]),
      },
      true,
    );

    // Update form field value when customPrice changes externally (e.g., when fixed price is selected)
    useEffect(() => {
      const currentField = customPriceForm.fields.get("customPrice");
      const newValue = customPrice?.toString() || "";

      if (currentField && currentField.value !== newValue) {
        // Reset validation state to untouched (isValid: null) so a previously triggered
        // error text does not persist when the value is changed externally (e.g. a fixed
        // price is selected, or the custom price is cleared).
        const updatedField = { ...currentField, value: newValue, isValid: null };
        setForm({
          fields: new Map(customPriceForm.fields).set("customPrice", updatedField),
        });
      }
    }, [customPrice, customPriceForm.fields, setForm]);

    // Note: useImperativeHandle is intentionally used here to expose validation logic to parent components.
    // This allows parents to trigger validation and focus invalid fields before form submission,
    // which is cleaner than lifting all validation state up or passing validation callbacks down.
    useImperativeHandle(ref, () => ({
      validatePrice: () => {
        // If a fixed amount is selected, validation passes
        if (hasFixedAmounts && selectedPriceVariation) {
          return true;
        }

        // Validate custom price (either no fixed amounts exist, or none selected)
        const { form: validatedForm } = getFormValidation();
        const customPriceField = validatedForm.fields.get("customPrice");

        if (customPriceField?.isValid !== true) {
          focusOn("customPrice", true);
          return false;
        }

        return true;
      },
    }));

    // Auto-select first fixed amount on mount if enabled
    useEffect(() => {
      if (hasFixedAmounts && selectedPriceVariation === null && customPrice === undefined) {
        setSelectedPriceVariation(giftCardFixedAmounts[0]);
      }
    }, [hasFixedAmounts, giftCardFixedAmounts, setSelectedPriceVariation, customPrice, selectedPriceVariation]);

    return (
      <>
        {hasFixedAmounts && (
          <PriceVariationSelector
            priceVariation={giftCardFixedAmounts}
            setSelectedPriceVariation={setSelectedPriceVariation}
            selectedPriceVariation={selectedPriceVariation}
          />
        )}
        {hasCustomPrice && minGiftCardOptionalAmount && (
          <CustomPrice
            customPrice={customPrice}
            setCustomPrice={setCustomPrice}
            minCustomPrice={minGiftCardOptionalAmount}
            maxCustomPrice={maxGiftCardOptionalAmount}
            inputLabel={
              hasFixedAmounts ? "productBlockOptionalCustomPriceInputLabel" : "productBlockCustomPriceInputLabel"
            }
            formField={customPriceForm.fields.get("customPrice")}
            onChange={handleCustomPriceFieldChange}
          />
        )}
      </>
    );
  },
);

GiftCardPriceSelector.displayName = "GiftCardPriceSelector";
