import { useCallback, useMemo, useState } from "react";
import { isNumber } from "lodash-es";
import { useTranslation } from "react-i18next";
import { NormalizedProduct } from "./product-hooks";

export type UsePurchasePanelStateReturn = {
  quantity: number;
  setQuantity: (qty: number) => void;
  productIsInStock: boolean;
  maxQuantity: number | undefined;
  isProductValid: (q: number) => boolean;
  addToCartLabel: (isAddingToCart: boolean) => string;
  totalValue: number | undefined;
  totalValueLabel: string;
};

type UsePurchasePanelStateProps = {
  product: NormalizedProduct;
  price: number | undefined;
};

/**
 * Shared state management for product purchase panels
 * Handles quantity selection, stock validation, and label generation
 */
export const usePurchasePanelState = ({ product, price }: UsePurchasePanelStateProps): UsePurchasePanelStateReturn => {
  const { t } = useTranslation();
  const { maximumQuantity, stockLevel } = product.glkProduct ?? {};
  const [quantity, setQuantity] = useState(1);

  const productIsInStock = typeof stockLevel !== "number" || stockLevel > 0;

  const maxQuantity = useMemo(() => {
    if (typeof maximumQuantity === "number") {
      if (productIsInStock && typeof stockLevel === "number") {
        return Math.min(maximumQuantity, stockLevel);
      }
      return maximumQuantity;
    }
    if (productIsInStock && typeof stockLevel === "number") {
      return stockLevel;
    }
    return undefined;
  }, [maximumQuantity, productIsInStock, stockLevel]);

  const isProductValid = useCallback(
    (q: number) => {
      const validQuantity = typeof stockLevel === "number" ? q <= stockLevel : true;
      const validPrice = typeof price === "number" && price >= 0;
      return validPrice ? validQuantity : false;
    },
    [price, stockLevel],
  );

  const addToCartLabel = useCallback(
    (isAddingToCart: boolean) => {
      const defaultLabel = isAddingToCart ? t("adding") : t("addToCart");
      return productIsInStock ? defaultLabel : t("soldOut");
    },
    [productIsInStock, t],
  );

  const totalValue = isNumber(price) ? price * quantity : undefined;
  const totalValueLabel = t("total");

  return {
    quantity,
    setQuantity,
    productIsInStock,
    maxQuantity,
    isProductValid,
    addToCartLabel,
    totalValue,
    totalValueLabel,
  };
};
