import structure from "@/core/styling/structure.module.less";
import styles from "./product-block.module.less";
import { ProductBlockFragment } from "@/core/types";
import { GlobalContextType } from "@/core/contexts";
import { multipleClassNames, throwError, EventAggregator, getGiftCardSettings } from "@/core/helpers";
import { PrimaryButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import ProductNewCardForm from "@/core/components/modules/product-new-card-form/product-new-card-form";
import { usePurchasePanelState, useProductTracking, useAddToCartFlow } from "@/core/hooks";
import ProductPrice from "@/core/components/primitives/product-price/product-price";
import { NormalizedProduct, useProduct, useProductByContentfulId } from "@/core/hooks/product-hooks";
import { GiftCardPurchasePanel } from "./gift-card";
import PurchasePanelLayout from "@/core/components/blocks/product-block/components/purchase-panel-layout/purchase-panel-layout";
import ImageAndName from "@/core/components/blocks/product-block/components/image-and-name/image-and-name";
import { useTranslation } from "react-i18next";

export type BlackWeekProps = {
  enableBlackWeekOffer: boolean;
  blackWeekOfferLabelId: string;
  blackWeekOfferLabel: string;
};
type ContextValues = Pick<GlobalContextType, "showMenu" | "showCart" | "showSearch">;

const ProductInfoSection = ({
  preamble,
  description: descriptionMarkdown,
  readMoreText,
  readMoreLabel,
}: Pick<ProductBlockFragment, "preamble" | "readMoreLabel" | "description" | "readMoreText">) => {
  const description = descriptionMarkdown?.childMarkdownRemark?.html;
  const readMoreBody = readMoreText?.childMarkdownRemark?.html;

  return (
    <>
      {preamble && <p className="body-l">{preamble.preamble}</p>}
      {description && <div dangerouslySetInnerHTML={{ __html: description }}></div>}
      {readMoreBody && (
        <div className={styles.readMoreWrapper} data-no-other-info={!preamble && !description}>
          <ExpandContent
            showMoreLabelOverride={readMoreLabel ?? undefined}
            buttonType="ghost"
            buttonPosition="top"
            removeChildrenWhenUnexpanded
          >
            <div dangerouslySetInnerHTML={{ __html: readMoreBody }} className={styles.readMoreBody}></div>
          </ExpandContent>
        </div>
      )}
    </>
  );
};

type ProductPurchasePanelProps = {
  product: NormalizedProduct;
  setContextValues: (values: ContextValues) => void;
};
export const ProductPurchasePanel = ({ product, setContextValues }: ProductPurchasePanelProps) => {
  const { t } = useTranslation();
  const { priceIncludingVat: price, ordinaryPrice: previousPrice } =
    product.glkProduct ?? throwError("Must have GLK product");
  const { customPriceText } = product.contentfulProduct ?? throwError("Must have CF product");

  const {
    quantity,
    setQuantity,
    productIsInStock,
    maxQuantity,
    isProductValid,
    addToCartLabel,
    totalValue,
    totalValueLabel,
  } = usePurchasePanelState({
    product,
    price,
  });

  const { handleAddToCart, isAddingToCart } = useAddToCartFlow({
    product,
    price,
    quantity,
    setQuantity,
    setContextValues,
    isVariablePrice: false,
  });

  return (
    <PurchasePanelLayout
      quantity={quantity}
      onQuantityChanged={setQuantity}
      maxQuantity={maxQuantity}
      productIsInStock={productIsInStock}
      totalValue={totalValue}
      totalValueLabel={totalValueLabel}
      buttonLabel={addToCartLabel(isAddingToCart)}
      onAddToCart={handleAddToCart}
      isAddingToCart={isAddingToCart}
      isProductValid={isProductValid(quantity)}
      quantityPresenterOverride={t("pieces", { count: quantity })}
    >
      {price && (
        <div className={styles.price}>
          <ProductPrice
            price={price}
            previousPrice={previousPrice}
            customPriceText={customPriceText}
            priceClassName={multipleClassNames("heading-s", styles.priceWrapper)}
            ignoreComponentTheme={true}
          />
        </div>
      )}
    </PurchasePanelLayout>
  );
};

type ProductOverviewProps = {
  productId: number;
  blackWeekProps?: BlackWeekProps;
  setContextValues: (values: ContextValues) => void;
};
const ProductOverview = ({ productId, blackWeekProps, setContextValues }: ProductOverviewProps) => {
  const { t } = useTranslation();
  const product = useProduct(productId) ?? throwError("Should have GLK ID");
  const { optionalLinkUrl, optionalLinkLabelText, enableRegistrationForm, productData } =
    product.contentfulProduct ?? throwError("Should have both GLK ID and CF product");
  const { isGiftCardProduct } = getGiftCardSettings(product);

  function renderContent() {
    if (enableRegistrationForm && productData) {
      return <ProductNewCardForm product={product.glkProduct} />;
    }
    if (isGiftCardProduct) {
      return <GiftCardPurchasePanel product={product} setContextValues={setContextValues} />;
    }
    return <ProductPurchasePanel product={product} setContextValues={setContextValues} />;
  }

  return (
    <div className={styles.descriptionWrapper}>
      {blackWeekProps?.enableBlackWeekOffer && (
        <p
          className={multipleClassNames("heading-xs", styles.blackWeekLabel)}
          data-contentful-label-id={blackWeekProps.blackWeekOfferLabelId}
        >
          {blackWeekProps.blackWeekOfferLabel}
        </p>
      )}
      {optionalLinkUrl ? (
        <div className={styles.cartActionWrapper}>
          <PrimaryButtonLink
            label={optionalLinkLabelText || t("readMore")}
            className="waves-effect"
            url={optionalLinkUrl}
          />
        </div>
      ) : (
        renderContent()
      )}
    </div>
  );
};

export type ProductBlockProps = ProductBlockFragment & {
  // Comes from sites
  blackWeekProps?: BlackWeekProps;
  setContextValues: (values: Partial<ContextValues>) => void;
};
const ProductBlock = ({ contentful_id, blackWeekProps, setContextValues }: ProductBlockProps) => {
  const product = useProductByContentfulId(contentful_id);
  // Track product view when loaded
  useProductTracking(product);

  if (!product) {
    const error = new Error("Invalid product data");
    EventAggregator.publish("trackException", {
      exception: error,
      customMessage: "Error fetching extended product",
    });
    throw error;
  }

  const {
    productImage,
    componentTheme,
    backgroundColor,
    contentful_id: contentfulId,
    label,
  } = product.contentfulProduct;

  const image = productImage?.largeGatsbyImageData ?? productImage?.gatsbyImageData ?? null;

  return (
    <section
      data-contentful-id={contentfulId}
      className={multipleClassNames(
        styles.outerWrapper,
        componentTheme && `component-theme component-theme-${componentTheme} ${componentTheme}`,
      )}
    >
      <div
        className={multipleClassNames(
          structure.blockMaxWidthS,
          styles.innerWrapper,
          backgroundColor && styles.hasBackground,
        )}
      >
        <ImageAndName image={image} productName={product.name} label={label} />
        <ProductOverview
          productId={product.productId ?? 0}
          blackWeekProps={blackWeekProps}
          setContextValues={setContextValues}
        />
        <ProductInfoSection {...product.contentfulProduct} />
      </div>
    </section>
  );
};

export default ProductBlock;
