import styles from "./image-and-name.module.less";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import Label from "@/core/components/primitives/label/label";
import { useTranslation } from "react-i18next";

const ImageAndName = ({
  image,
  productName,
  label,
  centerAlignName = false,
}: {
  image: IGatsbyImageData | null;
  productName: string | null;
  label: string | null;
  centerAlignName?: boolean;
}) => {
  const { t } = useTranslation();

  return (
    <div className={styles.imageAndName}>
      <div className={styles.imageWrapper}>
        {image && <GatsbyImage image={image} className={styles.image} alt={productName ?? t("image")} />}
        {label && (
          <div className={styles.labelWrapper}>
            <Label title={label} textSize="xs" />
          </div>
        )}
      </div>
      <h1 className={styles.name} data-center-align-name={centerAlignName}>
        {productName}
      </h1>
    </div>
  );
};

export default ImageAndName;
