import { useCallback, useState, useRef } from "react";
import { useTranslation } from "react-i18next";
import { GlobalContextType } from "@/core/contexts";
import { getGiftCardSettings } from "@/core/helpers";
import { useEffectivePrice, usePurchasePanelState, useAddToCartFlow, GlkBackedProduct } from "@/core/hooks";
import { GiftCardPriceSelector, GiftCardPriceSelectorRef } from "./gift-card-price-selector";
import PurchasePanelLayout from "../components/purchase-panel-layout/purchase-panel-layout";

type ContextValues = Pick<GlobalContextType, "showMenu" | "showCart" | "showSearch">;

type GiftCardPurchasePanelProps = {
  product: GlkBackedProduct;
  setContextValues: (values: ContextValues) => void;
};

export const GiftCardPurchasePanel = ({ product, setContextValues }: GiftCardPurchasePanelProps) => {
  const { t } = useTranslation();
  const { giftCardFixedAmounts } = getGiftCardSettings(product);
  const [selectedPriceVariation, setSelectedPriceVariation] = useState(giftCardFixedAmounts?.[0] || null);
  const [customPrice, setCustomPrice] = useState<number | undefined>(undefined);
  const priceSelectorRef = useRef<GiftCardPriceSelectorRef>(null);

  // Enforce mutual exclusivity: selecting a variation clears custom price, and vice versa
  const handlePriceVariationChange = useCallback((value: number | null) => {
    setSelectedPriceVariation(value);
    setCustomPrice(undefined); // Clear custom price when selecting variation
  }, []);

  const handleCustomPriceChange = useCallback((amount: number | undefined) => {
    setCustomPrice(amount);
    if (amount !== undefined) {
      setSelectedPriceVariation(null); // Clear variation when entering custom price
    }
  }, []);

  const { effectivePrice, isVariablePrice } = useEffectivePrice(product, selectedPriceVariation, customPrice);

  const {
    quantity,
    setQuantity,
    productIsInStock,
    maxQuantity,
    isProductValid,
    addToCartLabel,
    totalValue,
    totalValueLabel,
  } = usePurchasePanelState({
    product,
    price: effectivePrice,
  });

  const { handleAddToCart: originalHandleAddToCart, isAddingToCart } = useAddToCartFlow({
    product,
    price: effectivePrice,
    quantity,
    setQuantity,
    setContextValues,
    isVariablePrice,
  });

  // Wrap handleAddToCart to validate price and focus if invalid
  const handleAddToCart = useCallback(async () => {
    // Validate price selection (validatePrice focuses invalid field internally)
    if (priceSelectorRef.current && !priceSelectorRef.current.validatePrice()) {
      return; // Validation failed
    }

    await originalHandleAddToCart();
  }, [originalHandleAddToCart]);

  return (
    <PurchasePanelLayout
      quantity={quantity}
      onQuantityChanged={setQuantity}
      maxQuantity={maxQuantity}
      productIsInStock={productIsInStock}
      totalValue={totalValue}
      totalValueLabel={totalValueLabel}
      buttonLabel={addToCartLabel(isAddingToCart)}
      onAddToCart={handleAddToCart}
      isAddingToCart={isAddingToCart}
      isProductValid={isProductValid(quantity)}
      quantityLabel={t("quantity")}
      quantityPresenterOverride={t("pieces", { count: quantity })}
    >
      <GiftCardPriceSelector
        ref={priceSelectorRef}
        product={product}
        selectedPriceVariation={selectedPriceVariation}
        setSelectedPriceVariation={handlePriceVariationChange}
        customPrice={customPrice}
        setCustomPrice={handleCustomPriceChange}
      />
    </PurchasePanelLayout>
  );
};
