import { getGiftCardSettings } from "@/core/helpers";
import { useMemo } from "react";
import { GlkBackedProduct } from "./product-hooks";

export type PriceCalculationResult = {
  effectivePrice: number;
  isVariablePrice: boolean;
};

/**
 * Shared hook for calculating effective product price based on user selections
 * Used by both product-block and giftable-product-block components
 */
export const useEffectivePrice = (
  product: GlkBackedProduct,
  selectedPriceVariation: number | null,
  customPrice: number | undefined,
): PriceCalculationResult => {
  return useMemo(() => {
    const { minGiftCardOptionalAmount, giftCardFixedAmounts } = getGiftCardSettings(product);

    // Priority: optional amount > selected variation > default price
    if (minGiftCardOptionalAmount && customPrice !== undefined && customPrice > 0) {
      return {
        effectivePrice: customPrice,
        isVariablePrice: true,
      };
    }

    if (giftCardFixedAmounts && selectedPriceVariation) {
      return {
        effectivePrice: selectedPriceVariation,
        isVariablePrice: true,
      };
    }

    return {
      effectivePrice: product.glkProduct.priceIncludingVat,
      isVariablePrice: false,
    };
  }, [product, selectedPriceVariation, customPrice]);
};
