// @ts-strict-ignore
import { Ref, useRef } from "react";
import styles from "./image-field.module.less";
import PropTypes from "prop-types";
import { OutlineButton } from "@/core/components/primitives/parks-button/parks-button";
import { FormField, assignToRefs } from "@/core/helpers/form-builder";
import Icon from "@/core/components/primitives/icon/icon";
import { useTranslation } from "react-i18next";
import InputLabel from "@/core/components/primitives/input-label/input-label";
import InputHelperText from "@/core/components/primitives/input-helper-text/input-helper-text";
import InputError from "@/core/components/primitives/input-error/input-error";

type ImageFieldProps = {
  formField: FormField;
  onUserChanged: CallableFunction;
  isValid?: boolean;
  isRequired?: boolean;
  label?: string;
  helperText?: string;
  inputRef?: Ref<HTMLButtonElement>;
};

const ImageField = ({
  formField,
  onUserChanged,
  isValid,
  isRequired,
  label,
  helperText,
  inputRef,
}: ImageFieldProps) => {
  const fileInput = useRef(null);
  const { t } = useTranslation();

  if (formField) {
    isValid = isValid ? isValid : formField.isValid;
    isRequired = isRequired ? isRequired : formField.isRequired;
    label = label ? label : formField.label;
    helperText = helperText ? helperText : formField.helperText;
  }

  const displayError = isValid === false;

  const handleBase64Image = (event) => {
    // Get file
    if (!event.target.files || !event.target.files[0]) {
      return;
    }
    const canvas = document.getElementById("base64Image") as HTMLCanvasElement;
    const context = canvas.getContext("2d");
    const fileReader = new FileReader();
    fileReader.addEventListener("load", (evt) => {
      const img: HTMLImageElement = new Image();
      img.addEventListener("load", () => {
        if (img.width > img.height) {
          // Cap size of landscape oriented photos
          canvas.width = Math.min(img.width, 750);
          canvas.height = Math.round(canvas.width * (img.height / img.width));
        } else {
          // Cap size of portrait oriented photos
          canvas.height = Math.min(img.height, 750);
          canvas.width = Math.round(canvas.height * (img.width / img.height));
        }
        context.clearRect(0, 0, context.canvas.width, context.canvas.height);
        context.drawImage(img, 0, 0, canvas.width, canvas.height);
        let base64Url = canvas.toDataURL("image/jpeg", 0.75);
        const output = base64Url.replace(/^data:image\/jpe?g;base64,/, "");
        onUserChanged(formField.name, output);
        // Clear canvas after base64 image has been generated
        context.clearRect(0, 0, context.canvas.width, context.canvas.height);
        canvas.height = 0;
        canvas.width = 0;
        base64Url = null;
      });
      img.src = evt.target.result as string;
    });
    fileReader.readAsDataURL(event.target.files[0]);
  };

  const triggerUpload = () => {
    fileInput.current.click();
  };

  let base64Image = formField.value;
  if (base64Image && base64Image.indexOf("base64,") === -1) {
    base64Image = `data:image;base64,${base64Image}`;
  }

  const getBackgroundImage = () => {
    if (base64Image) {
      return `url(${base64Image}) no-repeat center / cover`;
    }
    return null;
  };

  return (
    <div className={styles.imageField}>
      <InputLabel label={label} inputName={label} isRequired={isRequired} />
      <div role="button" aria-pressed="false" tabIndex={0} className={styles.uploadContainer} onClick={triggerUpload}>
        <input onChange={handleBase64Image} ref={fileInput} type="file" />
        <canvas className={styles.base64Image} id="base64Image"></canvas>
        {getBackgroundImage() ? (
          <div className={styles.imageChangeImageWrapper}>
            <h5 className={styles.selectedProfileImageHeading}>{t("imageChosen")}</h5>
            <div className={styles.profileImage} style={{ background: getBackgroundImage() }}></div>
            <OutlineButton
              ref={(e) => assignToRefs(e, inputRef, formField?.inputRef)}
              className={styles.button}
              label={t("imageChange")}
            />
          </div>
        ) : (
          <div className={styles.infoButtonWrapper}>
            <div className={styles.iconWrapper}>
              <Icon name="file-upload" size="xxl" />
            </div>
            <OutlineButton
              ref={(e) => assignToRefs(e, inputRef, formField?.inputRef)}
              className={styles.button}
              label={t("imageIDUpload")}
            />
          </div>
        )}
      </div>
      {helperText && <InputHelperText helperText={helperText} />}
      <InputError showError={displayError} isRequired={isRequired} errorText={t("inputValidationImageID")} />
    </div>
  );
};

export default ImageField;

ImageField.propTypes = {
  previewImageUrl: PropTypes.string,
  onUserChanged: PropTypes.func,
  imageField: PropTypes.object,
  label: PropTypes.string,
};
