import { useCallback } from "react";
import { CartRequestCartItem, UpdateCartErrorCodeErrorResponse } from "@parksandresorts/webapiproxy-types";
import { EventAggregator, NotificationHelper } from "@/core/helpers";
import { updateCartErrorCodeMessage } from "@/core/helpers/jetpass-helper";
import { useIsMobile } from "@/core/hooks/use-is-mobile";
import { useShopServiceCartContext } from "@/core/contexts";
import { NormalizedProduct } from "@/core/hooks/product-hooks";
import { useTranslation } from "react-i18next";

export type AddToCartSuccessActions = {
  showCart?: () => void;
  showCartNotification?: boolean;
  // clean the state through dispatch
  cleanState?: () => void;
};

type UseProductBlockCartOperationsArgs = {
  product: NormalizedProduct;
  successActions?: AddToCartSuccessActions;
};

/**
 * Shared hook for cart operations with consistent error handling and notifications
 * Used by both product-block and giftable-product-block components
 */
export const useProductBlockCartOperations = ({ product, successActions }: UseProductBlockCartOperationsArgs) => {
  const { t } = useTranslation();
  const isMobileView = useIsMobile();
  const { addCartItem, addMultipleCartItems, isLoading } = useShopServiceCartContext();

  const addToCartWithErrorHandling = useCallback(
    async (cartItems: CartRequestCartItem | Array<CartRequestCartItem>) => {
      try {
        // Handle both single item and multiple items
        if (Array.isArray(cartItems)) {
          await addMultipleCartItems(cartItems);
        } else {
          await addCartItem(cartItems);
        }

        // Success handling
        if (isMobileView && successActions?.showCartNotification !== false) {
          NotificationHelper.addCartNotification({
            headline: product.contentfulProduct?.addedToCartHeadline || t("addedToCartHeadline"),
            body: product.contentfulProduct?.addedToCartBody || t("addedToCartBody"),
          });
        } else if (successActions?.showCart) {
          successActions.showCart();
        }

        if (successActions?.cleanState) {
          successActions.cleanState();
        }

        return true;
      } catch (err) {
        // Track the exception for analytics
        EventAggregator.publish("trackException", {
          exception: err,
          customMessage: "Error adding item to cart",
        });

        // Handle error messaging
        const errorCodeResponse = err as { error?: UpdateCartErrorCodeErrorResponse };
        if (errorCodeResponse?.error) {
          const { headline, body } = updateCartErrorCodeMessage(errorCodeResponse.error);
          NotificationHelper.addNotification({
            headline,
            body,
            notificationType: "WARNING_NOTIFICATION",
            displayTime: "TIME_PERSISTENT",
          });
        } else {
          NotificationHelper.addNotification({
            headline: t("addToCartErrorHeadline"),
            body: t("addToCartErrorBody"),
            notificationType: "WARNING_NOTIFICATION",
            displayTime: "TIME_PERSISTENT",
          });
        }

        console.error("Error adding to cart:", err);
        return false;
      }
    },
    [product, addCartItem, addMultipleCartItems, isMobileView, successActions, t],
  );

  return {
    addToCartWithErrorHandling,
    isAddingToCart: isLoading,
  };
};
