import { GlkBackedProduct } from "../hooks";

/**
 * Shared helper to extract and provide gift card settings from a product
 * Used by both product-block and giftable-product-block components
 */
export const getGiftCardSettings = (product: GlkBackedProduct) => {
  const giftCardSettings = product.glkProduct.metadata?.giftCardSettings;

  return {
    giftCardSettings,
    giftCardFixedAmounts: giftCardSettings?.giftCardFixedAmounts,
    minGiftCardOptionalAmount: giftCardSettings?.minGiftCardOptionalAmount,
    maxGiftCardOptionalAmount: giftCardSettings?.maxGiftCardOptionalAmount,
    hasFixedAmounts: Boolean(giftCardSettings?.giftCardFixedAmounts?.length),
    hasCustomPrice: Boolean(giftCardSettings?.minGiftCardOptionalAmount),
    isGiftCardProduct: Boolean(giftCardSettings),
  };
};
