import { useCallback } from "react";
import { DeliveryType } from "@parksandresorts/webapiproxy-types";
import { useIsMobile } from "@/core/hooks/use-is-mobile";
import { NormalizedProduct } from "./product-hooks";
import { useProductBlockCartOperations } from "@/core/hooks/use-product-block-cart-operations";
import { createCartItem, createMultipleCartItems } from "@/core/helpers/cart-item-builder";
import { getPrimaryDeliveryType } from "../helpers/product-helper";

type UseAddToCartArgs = {
  product: NormalizedProduct;
  price: number | null;
  quantity: number;
  setQuantity: (q: number) => void;
  setContextValues: (vals: { showMenu: boolean; showCart: boolean; showSearch: boolean }) => void;
  isVariablePrice?: boolean; // Whether this is a variable price (optional amount or selected variation) vs default product price
};

// Hook to manage add-to-cart flow with side effects & notifications
export const useAddToCartFlow = ({
  product,
  price,
  quantity,
  setQuantity,
  setContextValues,
  isVariablePrice = false,
}: UseAddToCartArgs) => {
  const isMobileView = useIsMobile();
  const shouldAddMultipleItems = quantity > 1 && isVariablePrice && price !== null;
  const { addToCartWithErrorHandling, isAddingToCart } = useProductBlockCartOperations({
    product,
    successActions: {
      showCart: () => setContextValues({ showCart: true, showMenu: false, showSearch: false }),
      showCartNotification: isMobileView,
    },
  });

  const handleAdd = useCallback(async () => {
    const deliveryType = getPrimaryDeliveryType(product, DeliveryType.DIGITAL);

    if (shouldAddMultipleItems) {
      const items = createMultipleCartItems(product, {
        price,
        isVariablePrice,
        deliveryType,
        quantity,
      });
      await addToCartWithErrorHandling(items);
    } else {
      const item = createCartItem(product, {
        price: price ?? undefined,
        isVariablePrice,
        deliveryType,
        quantity,
      });
      await addToCartWithErrorHandling(item);
    }

    setQuantity(1);
  }, [addToCartWithErrorHandling, product, quantity, price, isVariablePrice, setQuantity, shouldAddMultipleItems]);

  return { handleAddToCart: handleAdd, isAddingToCart };
};
