import styles from "./purchase-panel-layout.module.less";
import { PropsWithChildren } from "react";
import { CurrencyHelper, multipleClassNames } from "@/core/helpers";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import QuantitySelector from "@/core/components/primitives/quantity-selector/quantity-selector";
import AnimationPop from "@/core/components/primitives/animation-pop/animation-pop";

type PurchasePanelLayoutProps = {
  quantity: number;
  onQuantityChanged: (qty: number) => void;
  /** Maximum allowed quantity (undefined = no limit) */
  maxQuantity: number | undefined;
  productIsInStock: boolean;
  totalValue: number | undefined;
  totalValueLabel: string;
  buttonLabel: string;
  onAddToCart: () => void;
  isAddingToCart: boolean;
  isProductValid: boolean;
  quantityLabel?: string;
  /** Presenter override for quantity (e.g., "2 pieces") */
  quantityPresenterOverride: string;
};

/**
 * Shared purchase panel layout component
 * Handles the common UI structure for product and gift card purchase panels
 */
const PurchasePanelLayout = ({
  quantity,
  onQuantityChanged,
  maxQuantity,
  productIsInStock,
  totalValue,
  totalValueLabel,
  buttonLabel,
  onAddToCart,
  isAddingToCart,
  isProductValid,
  quantityLabel,
  quantityPresenterOverride,
  children,
}: PropsWithChildren<PurchasePanelLayoutProps>) => {
  return (
    <div className={styles.cartActionWrapper}>
      <div className={styles.priceAndQuantityWrapper} data-has-quantity-label={!!quantityLabel}>
        {children}
        <div className={styles.quantitySection}>
          {quantityLabel && <p className={multipleClassNames("bold", styles.quantityLabel)}>{quantityLabel}</p>}
          <QuantitySelector
            quantity={quantity}
            maxQuantity={maxQuantity}
            minQuantity={1}
            isDisabled={!productIsInStock}
            quantityPresentatorOverride={quantityPresenterOverride}
            onQuantityChanged={onQuantityChanged}
            wrapperClassName={multipleClassNames(styles.quantityWrapper, "fade-in")}
            classNameLeftButton={multipleClassNames(styles.quantityLeftButton, "waves-effect")}
            classNameRightButton={multipleClassNames(styles.quantityRightButton, "waves-effect")}
            quantityClassName={styles.quantity}
          />
        </div>
      </div>
      <div className={styles.addToCart}>
        <p className={styles.totalPrice}>
          {totalValueLabel}{" "}
          <AnimationPop>{totalValue !== undefined ? CurrencyHelper.formatToSek(totalValue) : "-"}</AnimationPop>
        </p>
        <PrimaryButton
          label={buttonLabel}
          isFullWidth
          className={multipleClassNames("waves-effect", isAddingToCart && styles.isLoading)}
          iconLeftNew={isAddingToCart ? "loading" : undefined}
          onClick={onAddToCart}
          isDisabled={!isProductValid || isAddingToCart}
        />
      </div>
    </div>
  );
};

export default PurchasePanelLayout;
